1	use crate::prelude::*;
2	use crate::shared::TextPrintMode;
3	use biome_formatter::{FormatRuleWithOptions, write};
4	use biome_markdown_syntax::{MdTextual, MdTextualFields};
5	
6	#[derive(Debug, Clone, Default)]
7	pub(crate) struct FormatMdTextual {
8	    should_remove: bool,
9	    trim_start: bool,
10	    print_mode: TextPrintMode,
11	}
12	impl FormatNodeRule<MdTextual> for FormatMdTextual {
13	    fn fmt_fields(&self, node: &MdTextual, f: &mut MarkdownFormatter) -> FormatResult<()> {
14	        let MdTextualFields { value_token } = node.as_fields();
15	
16	        let value_token = value_token?;
17	
18	        if self.should_remove {
19	            format_removed(&value_token).fmt(f)
20	        } else if self.print_mode.is_clean() {
21	            // Clean mode: strip spaces/tabs but preserve newlines.
22	            // Used for code block content where trailing whitespace on empty
23	            // lines should be removed but newlines must be kept.
24	            let cleaned = value_token
25	                .text()
26	                .trim_matches(|c: char| c == ' ' || c == '\t');
27	            if cleaned == value_token.text() {
28	                write!(f, [value_token.format()])
29	            } else {
30	                write!(
31	                    f,
32	                    [format_replaced(
33	                        &value_token,
34	                        &text(cleaned, value_token.text_trimmed_range().start())
35	                    )]
36	                )
37	            }
38	        } else if self.print_mode.is_normalize_words() {
39	            // Collapse whitespace: words are joined with hard_space,
40	            // leading/trailing whitespace becomes a single hard_space.
41	            let raw = value_token.text();
42	            let words: Vec<&str> = raw.split_whitespace().collect();
43	
44	            if words.is_empty() {
45	                // Whitespace-only — normalize to a single hard_space.
46	                write!(f, [format_replaced(&value_token, &hard_space())])
47	            } else {
48	                let has_leading_ws = raw.starts_with(char::is_whitespace);
49	                let has_trailing_ws = raw.ends_with(char::is_whitespace);
50	                let position = value_token.text_trimmed_range().start();
51	                write!(
52	                    f,
53	                    [format_replaced(
54	                        &value_token,
55	                        &format_with(|f| {
56	                            if has_leading_ws {
57	                                write!(f, [hard_space()])?;
58	                            }
59	                            for (i, word) in words.iter().enumerate() {
60	                                if i > 0 {
61	                                    write!(f, [hard_space()])?;
62	                                }
63	                                write!(f, [text(word, position)])?;
64	                            }
65	                            if has_trailing_ws {
66	                                write!(f, [hard_space()])?;
67	                            }
68	                            Ok(())
69	                        })
70	                    )]
71	                )
72	            }
73	        } else if self.trim_start {
74	            let trimmed_text = value_token.text().trim_start();
75	            write!(
76	                f,
77	                [format_replaced(
78	                    &value_token,
79	                    &text(trimmed_text, value_token.text_trimmed_range().start())
80	                )]
81	            )
82	        } else {
83	            write!(f, [value_token.format()])
84	        }
85	    }
86	}
