+/// The character used for fence delimiters in the formatted output.
+///
+/// The formatter always normalizes fenced code block delimiters to backticks
+/// (CommonMark §4.5), regardless of whether the source used backticks or
+/// tildes (`~~~`).
+const FENCE_CHAR: char = '`';
+
+#[derive(Debug, Clone, Default)]
+pub(crate) struct FormatMdFencedCodeBlock;
+impl FormatNodeRule<MdFencedCodeBlock> for FormatMdFencedCodeBlock {
+    fn fmt_fields(&self, node: &MdFencedCodeBlock, f: &mut MarkdownFormatter) -> FormatResult<()> {
+        let MdFencedCodeBlockFields {
+            l_fence,
+            r_fence,
+            r_fence_indent,
+            content,
+            code_list,
+            indent,
+        } = node.as_fields();
+
+        let l_fence = l_fence?;
+
+        // Compute the minimum fence length needed (CommonMark §4.5).
+        // The fence must be strictly longer than any backtick sequence in the
+        // content, otherwise the inner sequence would be parsed as a closing
+        // fence. E.g. if the content contains ``` (3 backticks), the outer
+        // fence needs at least 4. Since the output always uses backticks, only
+        // backtick sequences matter (tilde sequences are irrelevant).
+        let max_inner = longest_fence_char_sequence(node, FENCE_CHAR);
+        let fence_len = (max_inner + 1).max(3);
+        let normalized_fence: String = std::iter::repeat_n(FENCE_CHAR, fence_len).collect();
+
+        // The info string (language/metadata tag) is emitted immediately after
+        // the opening fence with no separating space. Leading and trailing
+        // whitespace is trimmed, but the internal structure (commas, multiple
+        // spaces between values) is preserved verbatim — e.g.
+        // `rust,  ignore   expect_diagnostics`.
+        let info_range = code_list.syntax().text_trimmed_range();
+        let info_owned = code_list.syntax().text_trimmed().to_string();
